def build_agent(sandbox):
    # Create a beam at x=6, y=1.0, width=1.2m, height=1.2m to anchor structure
    beam = sandbox.add_beam(x=6.0, y=1.0, width=1.2, height=1.2, angle=0, density=250.0)
    # Anchor the beam to the ground at its left end
    joint = sandbox.add_joint(beam, None, (6.0 - 0.6, 1.0 - 0.6), type='rigid')
    return beam

def agent_action(sandbox, agent_body, step_count):
    particles = sandbox.get_fluid_particles()
    for particle in particles:
        # Apply forward force to push towards target
        force_magnitude = 1.0
        sandbox.apply_force_to_particle(particle, force_magnitude, 0)

        # Check if in any pit
        in_pit = False
        if (11 <= particle.position.x <= 12.5) or (13.5 <= particle.position.x <= 15.5) or (16 <= particle.position.x <= 17.5):
            if (particle.position.y >= 0.0) and (particle.position.y <= 2.0):
                in_pit = True
        if in_pit:
            # Determine which pit it's in
            if 11 <= particle.position.x <= 12.5:
                pit_center = 11.75
                if particle.position.x < pit_center:
                    dx = 1.0
                else:
                    dx = -1.0
            elif 13.5 <= particle.position.x <= 15.5:
                pit_center = 14.5
                if particle.position.x < pit_center:
                    dx = 1.0
                else:
                    dx = -1.0
            elif 16 <= particle.position.x <= 17.5:
                pit_center = 16.75
                if particle.position.x < pit_center:
                    dx = 1.0
                else:
                    dx = -1.0
            # Apply lateral force to push away
            force_magnitude = 0.5 * dx
            sandbox.apply_force_to_particle(particle, force_magnitude, 0)

        # Apply vertical force to keep at y=1.0
        desired_y = 1.0
        current_y = particle.position.y
        delta_y = desired_y - current_y
        if delta_y != 0:
            force_magnitude = 0.5
            sandbox.apply_force_to_particle(particle, 0, delta_y * force_magnitude)

        # Apply upward force to counteract gravity well (if applicable)
        if 10 <= particle.position.x <= 14 and 1.5 <= current_y <= 3.5:
            force_magnitude = 0.5
            sandbox.apply_force_to_particle(particle, 0, force_magnitude)

        # Check for headwind (above y=3.0)
        if particle.position.y > 3.0:
            force_magnitude = 0.5
            sandbox.apply_force_to_particle(particle, 0, -force_magnitude)
